;---------------------------------------------------------------------------------------------------
; CalculatePartThrottleTransientFuel  ($6D87)
;
; Transient fuel: accelerator-pump style enrichment and deceleration lean-out. [reviewed - data
; flow]
;
; Runs in the main loop. Compares MAP and TPS with their filtered averages (time constants AETIME,
; THRTCN, LMAPTC, LOTIME vs coolant). A rise above MAPTRG / POSTRG (limited by MAPMAX / THRMAX)
; gives an additive pulse Pulsewidth_PartThrottleEnrichment_HB = delta x AESLOP or POSSLP (vs
; coolant). A fall gives the lean-out factors (LOTTHR, NEGSL2, triggers LOTTRG/LOTRG2/DECTRG with
; hysteresis, minimum RPM LOTRPM) and inhibits the O2 controller for DCELTM afterwards. AIS motor
; steps also produce a small enrichment or enleanment pulse (AISPL1/AISPL2/AISNLC) so idle mixture
; follows the air change.
;
; Called from: MainSubLoop
;---------------------------------------------------------------------------------------------------
CalculatePartThrottleTransientFuel:
        clra
        staa    <Temp2
        staa    <Temp3
        ldaa    <Timer_O2InhibitSwitchingRichIdleToClosedLoop
        beq     L6D93
        deca
        staa    <Timer_O2InhibitSwitchingRichIdleToClosedLoop
L6D93:
        ldaa    <CoolantTemp
        ldab    <MapValue
        subb    <MapPrevious
        stab    <Temp0
        bcs     TransFuel_CalculateDecreasingMAPTransientFuel
        ldx     #AETIME_EnrichmentTime_FromTemp      ; DCELTM: O2CNTR inhibit after MAP/THR leanout is done (times 11 ms)
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    <Factor_LeanoutOrEnrichTime_MAP
        clra
        staa    >Factor_DecelLeanoutWhenMAPDecreasing_Temp
        ldaa    >CONFIG_ConfigurationFlags           ; CONFIG: These are the factory configuration options.
        bita    #$02
        beq     TransFuel_CalculateIncreasingMAPTransientFuel
        brset   <BitFlags65,#$80,TransFuel_CalculateIncreasingMAPTransientFuel ; throttle open (off idle)
        jmp     >TransFuel_IncludeTPSTransients


;---------------------------------------------------------------------------------------------------
; TransFuel_CalculateIncreasingMAPTransientFuel  ($6DB7)
;---------------------------------------------------------------------------------------------------
TransFuel_CalculateIncreasingMAPTransientFuel:
        ldaa    <Temp0
        suba    >MAPTRG_DeltaMapTriggerLevelPartThrottle ; MAPTRG: MAP Delta required to trigger transient enrichment
        bcs     L6DD5
        cmpa    >MAPMAX_MaxDeltaMapAllowedPartThrottle ; MAPMAX: Maximum Delta MAP allowed
        bcs     L6DC6
        ldaa    >MAPMAX_MaxDeltaMapAllowedPartThrottle ; MAPMAX: Maximum Delta MAP allowed
L6DC6:
        staa    <Temp1
        ldaa    <CoolantTemp
        ldx     #AESLOP_DeltaMAPEnrichment_FromTemp  ; AESLOP: Transient Enrichment PW Addition
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        ldaa    <Temp1
        mul
        std     <Temp2
L6DD5:
        jmp     >TransFuel_IncludeTPSTransients


;---------------------------------------------------------------------------------------------------
; TransFuel_CalculateDecreasingMAPTransientFuel  ($6DD8)
;---------------------------------------------------------------------------------------------------
TransFuel_CalculateDecreasingMAPTransientFuel:
        ldx     #LMAPTC_TimeConstant                 ; LMAPTC: lean out time constant based on MAP
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    <Factor_LeanoutOrEnrichTime_MAP
        brset   <BitFlags65,#$01,L6E2C               ; wide-open throttle
        ldaa    <EngineRpm_HB
        cmpa    >LOTRPM_MinRpmForMapLeanout          ; LOTRPM: No map leanout if below this RPM
        bcs     L6E2C
        ldaa    >CONFIG_ConfigurationFlags           ; CONFIG: These are the factory configuration options.
        bita    #$20
        beq     L6DF6
        brclr   <BitFlags_AIS,#$08,L6E2C
L6DF6:
        brclr   <KeyOnOrEngineRunningTime,#$FF,L6E2C
        ldd     <VehicleSpeed_HB
        cpd     #$0080
        bcs     L6E2C
        ldaa    <Temp0
        nega
        ldab    >Factor_DecelLeanoutWhenMAPDecreasing_Temp
        beq     L6E0D
        adda    >DECHYS_DeltaMapHysteresisonTriggerLevels ; DECHYS: delta map hysteresis on trigger levels
L6E0D:
        cmpa    >LC337                               ; DECTRG: delta map trigger level for no incremental leanout
        bcs     L6E2C
        cmpa    >DECTRG_DeltaMapTriggerForNoIncrementalLeanoutp ; DTRG2: delta map trigger level for max leanout on decel
        bcs     L6E26
        ldaa    >DCELTM_O2CNTRInhibitAfterLeanoutDone ; DCELTM: O2CNTR inhibit after MAP/THR leanout is done (times 11 ms)
        staa    <Timer_O2InhibitSwitchingRichIdleToClosedLoop
        ldaa    <CoolantTemp
        ldx     #NEGSL2_DeltaMAPLeanout_FromTemp     ; DECEL (DecelLeanoutFactorMAP_FromTemp)
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        bra     L6E2D

L6E26:
        tstb
        beq     L6E30
        incb
        bra     L6E2D

L6E2C:
        clrb
L6E2D:
        stab    >Factor_DecelLeanoutWhenMAPDecreasing_Temp
L6E30:
        ldaa    <Counter_MainLoop
        bita    #$07
        bne     TransFuel_IncludeTPSTransients
        sei
        ldaa    <Factor_LeanoutOrEnrichTime_MAP
        bne     L6E40
        ldaa    <MapValue
        clrb
        bra     L6E56

L6E40:
        ldy     <MapPrevious
        jsr     >ScaleYbyA                           ; Y = Y x A / 256, rounded (16 x 8 bit fractional multiply).
        pshy
        ldaa    <MapValue
        ldab    <Factor_LeanoutOrEnrichTime_MAP
        mul
        tsy
        subd    $00,y
        puly
        addd    <MapPrevious
L6E56:
        std     <MapPrevious
        cli

;---------------------------------------------------------------------------------------------------
; TransFuel_IncludeTPSTransients  ($6E59)
;---------------------------------------------------------------------------------------------------
TransFuel_IncludeTPSTransients:
        ldaa    <CoolantTemp
        ldab    <TpsVolts
        subb    <TpsAverageValue_HB
        stab    >Temp1_X
        stab    <Temp0
        bcs     TransFuel_CalculateDecreasingTPSTransientFuel
        ldx     #THRTCN_EnrichmentTime_FromTemp      ; DCELTM: O2CNTR inhibit after MAP/THR leanout is done (times 11 ms)
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    <Factor_LeanoutOrEnrichTime_TPS
        clra
        staa    >Timer_OffThrottleFuelEnrich2
        staa    <Factor_DecelLeanoutWhenMAPDecreasing
        ldaa    <Temp0
        suba    >POSTRG_PositiveTransientTriggerLevel ; POSTRG: Positive Transient Enrich Trigger Level in volts times 0.02
        bcc     L6E7E
        jmp     >L6F1E

L6E7E:
        cmpa    >THRMAX_MaxDeltaTHR                  ; THRMAX: Max Delta THR (THR-AVTHR-POSTRG) - value of $26 is .51 volts
        bcs     L6E86
        ldaa    >THRMAX_MaxDeltaTHR                  ; THRMAX: Max Delta THR (THR-AVTHR-POSTRG) - value of $26 is .51 volts
L6E86:
        staa    <Temp1
        ldaa    <CoolantTemp
        ldx     #POSSLP_DeltaTPSEnrichment_FromTemp  ; POSSLP: Throttle Transient Enrich PW Addition
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        ldaa    <Temp1
        mul
        addd    <Temp2
        cpd     <Temp2
        bcc     L6E9C
        ldd     <Temp2
L6E9C:
        jmp     >L6F24


;---------------------------------------------------------------------------------------------------
; TransFuel_CalculateDecreasingTPSTransientFuel  ($6E9F)
;---------------------------------------------------------------------------------------------------
TransFuel_CalculateDecreasingTPSTransientFuel:
        ldx     #LOTIME_DecelLeanoutTimeConstant_FromTemp ; LOTIME: Leanout Time Constant based on Delta THR - uses average throttle
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    <Factor_LeanoutOrEnrichTime_TPS
        brclr   <KeyOnOrEngineRunningTime,#$FF,TransFuel_ClearLeanOutFactor
        ldd     <VehicleSpeed_HB
        cpd     #$0080
        bcs     TransFuel_ClearLeanOutFactor
        ldaa    <Temp0
        nega
        ldab    >Timer_OffThrottleFuelEnrich2
        beq     L6EBE
        adda    >LOTHYS_LeanoutDeltaThrottleHysteresis ; LOTHYS: hysteresis about delta THR trigger levels
L6EBE:
        cmpa    >LOTTRG_DeltaTriggerForDecelLeanout  ; LOTTHR: Decel leanout factor - THR based. When Y is zero, factor is 1.00
        bcs     TransFuel_ClearLeanOutFactor
        cmpa    >LOTRG2_SecondDecelLeanoutTrigger    ; LOTRG2: Second trigger - leanout inc toward 1 when between triggers
        bcs     L6ED2
        ldaa    <CoolantTemp
        ldx     #LOTTHR_DecelLeanoutFactor_FromTemp  ; LOTTHR: Decel leanout factor - THR based. When Y is zero, factor is 1.00
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        bra     TransFuel_StoreLeanOutFactor

L6ED2:
        tstb
        beq     L6EE8
        incb
        bra     TransFuel_StoreLeanOutFactor


;---------------------------------------------------------------------------------------------------
; TransFuel_ClearLeanOutFactor  ($6ED8)
;---------------------------------------------------------------------------------------------------
TransFuel_ClearLeanOutFactor:
        clrb

;---------------------------------------------------------------------------------------------------
; TransFuel_StoreLeanOutFactor  ($6ED9)
;---------------------------------------------------------------------------------------------------
TransFuel_StoreLeanOutFactor:
        stab    >Timer_OffThrottleFuelEnrich2
        beq     L6EE8
        ldaa    >Factor_DecelLeanoutWhenMAPDecreasing_Temp
        beq     L6EED
        mul
        adca    #$00
        bra     L6EEE

L6EE8:
        ldaa    >Factor_DecelLeanoutWhenMAPDecreasing_Temp
        bra     L6EEE

L6EED:
        tba
L6EEE:
        staa    <Factor_DecelLeanoutWhenMAPDecreasing
        beq     L6EF5
        bset    <BitFlags66,#$10
L6EF5:
        ldaa    <Counter_MainLoop
        bita    #$07
        bne     L6F1E
        sei
        ldaa    <Factor_LeanoutOrEnrichTime_TPS
        bne     L6F05
        ldaa    <TpsVolts
        clrb
        bra     L6F1B

L6F05:
        ldy     <TpsAverageValue_HB
        jsr     >ScaleYbyA                           ; Y = Y x A / 256, rounded (16 x 8 bit fractional multiply).
        pshy
        ldaa    <TpsVolts
        ldab    <Factor_LeanoutOrEnrichTime_TPS
        mul
        tsy
        subd    $00,y
        puly
        addd    <TpsAverageValue_HB
L6F1B:
        std     <TpsAverageValue_HB
        cli
L6F1E:
        brset   <BitFlags71,#$80,L6F7B               ; engine not running (stopped or cranking)
        ldd     <Temp2
L6F24:
        std     <Pulsewidth_PartThrottleEnrichment_HB
        brset   <BitFlags65,#$80,L6F7B               ; throttle open (off idle)
        ldaa    >SwitchPortAccessReg1
        bita    #$40
        bne     L6F7B
        ldaa    <DesiredNewAisPosition
        suba    <CurrentAisPosition
        bcs     L6F7B
        cmpa    >DeltaToDesiredAISPos
        bcs     L6F3F
        staa    >DeltaToDesiredAISPos
L6F3F:
        cmpa    >POSTIG_MinAisPulseRequireToTriggerEnrichment ; POSTIG: Min AIS pulse required to trigger enrichment (steps)
        bcs     L6F70
        clr     >AISEnleanmentPW
        ldaa    >DeltaToDesiredAISPos
        ldx     #AISPL1_AISEnrichmentFactorFromAISPulse ; AISNLC: AISEnleanmentPWFromCoolantTemp
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        psha
        ldaa    <CoolantTemp
        ldx     #AISPL2_AISEnrichmentFactorFromCoolantTemp ; AISPL2: AISEnrichmentFactorFromCoolantTemp
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        pulb
        psha
        mul
        adca    #$00
        asla
        asla
        pulb
        aba
        bcc     L6F66
        ldaa    #$FF
L6F66:
        tab
        clra
        asld
        asld
        asld
        asld
        std     <Pulsewidth_AISEnrichment_HB
        bra     L6F7E

L6F70:
        ldaa    <CoolantTemp
        ldx     #AISNLC_AISEnleanmentPWFromCoolantTemp ; AISNLC: AISEnleanmentPWFromCoolantTemp
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    >AISEnleanmentPW
L6F7B:
        clr     >DeltaToDesiredAISPos
L6F7E:
        rts


;---------------------------------------------------------------------------------------------------
; CalculateInjectorPulsewidthForStarting_MM  ($6F7F)
;
; Cranking fuel: pulse width from coolant temperature, engine position pulses, RPM and baro.
; [reviewed - data flow]
;
; Runs in the main loop. Uses STRTFL (vs coolant, limited by STRLMT), STFTMP/STFTM2, EPPMUL (vs
; engine position pulses since start), STFBAR (baro) and the RPM factors STFLID (closed throttle)
; / STFLOI (open throttle): start fuel = [STRTFL^2 x (1 - STFBAR - STFTMP) x EPPMUL + BATOFF x 4]
; x 4 us. It also sets Factor_StartFuelDecayIntoRunFuel from SFDCAY, applies the heat-soak
; correction (AllowForHeatSoakAfterStall) and cuts fuel while the throttle is opened more than
; UNLOAD above MINTHR ("clear flood", ThrottleFlooredWhileStarting_UnloadFuel).
;
; Called from: MainSubLoop
;---------------------------------------------------------------------------------------------------
CalculateInjectorPulsewidthForStarting_MM:
        brset   <BitFlags71,#$80,L6F89               ; engine not running (stopped or cranking)
        ldaa    <CoolantTemp
        staa    >CoolantTempCopy1
        rts

L6F89:
        ldd     #$0000
        std     <Pulsewidth_PartThrottleEnrichment_HB
        ldaa    <TpsVolts
        cmpa    #$D0
        bcc     L6F9D
        suba    <MINTHR_LowestSessionTPS
        bls     L6FA0
        cmpa    >UNLOAD_DeltaThrottleFrom_MINTHR_ToUnloadCrankingFuel ; UNLOAD (DeltaThrottleFrom_MINTHR_ToUnloadCrankingFuel)
        bcs     L6FA0
L6F9D:
        jmp     >ThrottleFlooredWhileStarting_UnloadFuel

L6FA0:
        jsr     >AllowForHeatSoakAfterStall          ; Raises the effective coolant temperature after a short stall (RUNTMP vs time stopped, limi
        brset   <BitFlags65,#$80,L6FAF               ; throttle open (off idle)
        cmpa    >STRLMT_ColdestTempAllowedAtClosedThrottle ; STRLMT: Coldest temperature accepted as input to STRTFL table - anything below
        bcc     L6FAF
        ldaa    >STRLMT_ColdestTempAllowedAtClosedThrottle ; STRLMT: Coldest temperature accepted as input to STRTFL table - anything below
L6FAF:
        ldx     #STRTFL_FuelStartFromCoolantTemp     ; STRTFL: Start fuel uSec = [ STRTFL * STRTFL * (1 - STFBAR - STFTMP) * EPPMUL +
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        mul
        std     <Temp0
        ldx     #STFLID_StartFuelIdleFactor_fromRPM  ; STFLID (StartFuelIdleFactor_fromRPM)
        brset   <BitFlags65,#$80,L6FC2               ; throttle open (off idle)
        ldx     #STFLOI_StartFuelOffIdleFactor_fromRPM ; STFLOI (StartFuelOffIdleFactor_fromRPM)
L6FC2:
        ldd     <EngineRpm_HB
        asld
        bcs     L6FCD
        asld
        bcs     L6FCD
        asld
        bcc     L6FCF
L6FCD:
        ldaa    #$FF
L6FCF:
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        ldy     <Temp0
        jsr     >ScaleYbyA                           ; Y = Y x A / 256, rounded (16 x 8 bit fractional multiply).
        sty     <Temp0
        ldaa    <Counter_EPP_MaxFF
        ldx     #EPPMUL_FuelStartFuelPerEPP          ; EPPMUL: Start fuel uSec = [ STRTFL * STRTFL * (1 - STFBAR - STFTMP) * EPPMUL +
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    <Temp4
        ldaa    <CoolantTemp
        ldx     #STFTMP_FuelStartFuelFromCoolant     ; STFTMP: Start fuel uSec = [ STRTFL * STRTFL * (1 - STFBAR - STFTMP) * EPPMUL +
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        ldaa    <Temp4
        mul
        adca    #$00
        beq     L7003
        tab
        comb
        ldaa    #$FF
        addd    #$0101
        ldy     <Temp0
        jsr     >ScaleYbyD_resultD                   ; D = Y x D / 256 (16 x 16 bit fractional multiply), saturating at $FFFF.
        std     <Temp0
L7003:
        ldaa    <BaroPressure
        ldx     #STFBAR_FuelStartReductionFromBaro   ; STFBAR: Start fuel uSec = [ STRTFL * STRTFL * (1 - STFBAR - STFTMP) * EPPMUL +
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    <Temp4
        ldaa    <CoolantTemp
        ldx     #STFTM2_FuelStartFuelFromCoolant2    ; STFTM2: Start fuel uSec = [ STRTFL * STRTFL * (1 - STFBAR - STFTMP) * EPPMUL +
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        ldaa    <Temp4
        mul
        adca    #$00
        beq     L702B
        tab
        comb
        ldaa    #$FF
        addd    #$0101
        ldy     <Temp0
        jsr     >ScaleYbyD_resultD                   ; D = Y x D / 256 (16 x 16 bit fractional multiply), saturating at $FFFF.
        bra     L702D

L702B:
        ldd     <Temp0
L702D:
        asld
        bcs     L7033
        asld
        bcc     L703B
L7033:
        ldd     #$FFFF
        bra     L703B


;---------------------------------------------------------------------------------------------------
; ThrottleFlooredWhileStarting_UnloadFuel  ($7038)
;---------------------------------------------------------------------------------------------------
ThrottleFlooredWhileStarting_UnloadFuel:
        ldd     #$0000
L703B:
        jsr     >TweakInjectorPW                     ; Diagnostic override of the injector pulse width.
        std     <InjectorPulsewidth_HB
        cli
        ldx     #SFDCAY_FuelStartDecayIntoRun        ; SFDCAY: Start fuel uSec = [ STRTFL * STRTFL * (1 - STFBAR - STFTMP) * EPPMUL +
        ldaa    <CoolantTemp
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    <Factor_StartFuelDecayIntoRunFuel
        rts
